ruleBookInfo.tocUrl:
@js:
let bid = java.get("bid");
let sign = getSign(bid, "t");
`http://s1.ftn178.com/v3/book/chapter.api?app=FTNovel&os=Android&pbv=v1.0.57&_t=${time}&channel=ft0001&vs=14&sign=${sign},{
  "body": "bid=${bid}&nsc=1&nci=1&gid=1&channel=ft0001&timestamp=${time}",
  "method": "POST"
}`

ruleSearch.bookUrl:
@js:
let tsign = java.get('tsign').split(',')
let bid = java.getString('$.bid')
java.put('bid', bid);
`http://s1.ftn178.com/v3/book6/detail.api?nci=1&channel=ft0001&bid=${bid}&timestamp=${tsign[1]}&nsc=1&sign=${tsign[0]}&app=FTNovel`

