function scrambleString(inputString, mode) {
    if (!inputString || typeof inputString !== "string") {
        return inputString;
    }

    let str = inputString;
    let modeType = mode % 5;

    switch (modeType) {
        case 0:
            return reverseString(str);

        case 1:
            return swapAdjacentPairs(str);

        case 2:
            return rotateThreeChars(str);

        case 3:
            return rotateString(str);

        case 4:
            return digitMapAndReverse(str);

        default:
            return str;
    }
}

function reverseString(str) {
    return str.split("").reverse().join("");
}

function swapAdjacentPairs(str) {
    if (str.length < 2) return str;

    let result = str.split("");

    for (let i = 0; i < result.length - 1; i += 2) {
        let temp = result[i];
        result[i] = result[i + 1];
        result[i + 1] = temp;
    }

    return result.join("");
}

function rotateThreeChars(str) {
    if (str.length < 3) return str;

    let result = str.split("");

    for (let i = 0; i < result.length - 2; i += 3) {
        if (i + 2 < result.length) {
            let temp = result[i + 2];
            result[i + 2] = result[i + 1];
            result[i + 1] = result[i];
            result[i] = temp;
        }
    }

    return result.join("");
}

function rotateString(str) {
    if (str.length <= 1) return str;

    let len = str.length;
    let mid = Math.floor(len / 2);
    if (len % 2 === 0) {
        return str.substring(mid) + str.substring(0, mid);
    } else {
        return str.substring(mid + 1) + str.charAt(mid) + str.substring(0, mid);
    }
}

function digitMapAndReverse(str, customMapping = null) {
    let defaultDigitMap = {
        0: "9",
        1: "8",
        2: "7",
        3: "6",
        4: "5",
        5: "4",
        6: "3",
        7: "2",
        8: "1",
        9: "0"
    };

    let digitMap = customMapping || defaultDigitMap;
    let result = str
        .split("")
        .map((char) => {
            if (/[0-9]/.test(char) && digitMap[char]) {
                return digitMap[char];
            }
            return char;
        })
        .join("");
    return reverseString(result);
}

function sign5(str1) {
    let lastChar = str1.charAt(str1.length - 1);
    let mode = lastChar.charCodeAt(0) - 48;

    let combinedString = str1 + "343341450";

    return scrambleString(combinedString, mode);
}

