    /* ---------- 32 bit 辅助 ---------- */
    // (x >>> n) | (x << (32-n)) 之后再 >>>0，避免符号扩展
    function ror32(x, n) {
        n &= 31;
        return ((x >>> n) | (x << (32 - n))) >>> 0;
    }
    function rol32(x, n) {
        n &= 31;
        return ((x << n) | (x >>> (32 - n))) >>> 0;
    }
    // 转大小端：0xAABBCCDD <-> 0xDDCCBBAA
    function bswap32(x) {
        return (((x & 0xff) << 24) | (((x >>> 8) & 0xff) << 16) | (((x >>> 16) & 0xff) << 8) | (x >>> 24)) >>> 0;
    }

    /* ---------- Key Expansion ---------- */
    function keyExpansion(keyBytes /* java byte[] 或 JS 数组 */) {
        var k = [];
        // 1. 取前 16 字节并做不足填充
        for (var i = 0; i < 16; i++) {
            if (i < keyBytes.length) {
                // 处理Java byte[]可能是负数的情况
                var b = keyBytes[i];
                k[i] = b < 0 ? b + 256 : b;
            } else {
                k[i] = sbox1[k[i - 1]];
            }
        }
        // 2. S-Box0 代换
        for (i = 0; i < 16; i++) k[i] = sbox0[k[i]];
        // 3. 4 × 32 bit 词，注意 little-endian → big-endian
        var w = [];
        for (i = 0; i < 4; i++) {
            var idx = i * 4;
            var val = (k[idx] | (k[idx + 1] << 8) | (k[idx + 2] << 16) | (k[idx + 3] << 24)) >>> 0;
            w[i] = bswap32(val);
        }
        return w; // [k0,k1,k2,k3]
    }

    /* ---------- 主加密 ---------- */
    function ssEncrypt(dataBytes, keyBytes) {
        if (!dataBytes || !keyBytes) return [];

        var k = keyExpansion(keyBytes);
        var k0 = k[0],
            k1 = k[1],
            k2 = k[2],
            k3 = k[3];

        var dataLen = dataBytes.length;
        var remainder = dataLen % 16;
        var padLen = remainder === 0 ? 16 : 16 - remainder;

        var total = dataLen + padLen + 6;
        var out = new Array(total); // ← 改成 JS 数组

        /* ---------- 头 6 字节 ---------- */
        out[0] = 0x74;
        out[1] = 0x63;
        out[2] = 3;
        out[3] = padLen;
        out[4] = 0;
        out[5] = 1;

        /* ---------- 原始数据 ---------- */
        for (var i = 0; i < dataLen; i++) {
            // 处理Java byte[]可能是负数的情况
            var b = dataBytes[i];
            out[6 + i] = b < 0 ? b + 256 : b;
        }

        /* ---------- 填充区域清零 ---------- */
        for (i = 6 + dataLen; i < 6 + dataLen + padLen; i++) {
            out[i] = 0;
        }

        /* ---------- S-Box 替换 ---------- */
        for (i = 6; i < 6 + dataLen + padLen; i++) out[i] = sbox0[out[i]];

        /* ---------- 16-byte 块加密 ---------- */
        var nBlocks = (dataLen + padLen) / 16;
        for (var blk = 0; blk < nBlocks; blk++) {
            var base = 6 + blk * 16;

            // little-endian 读取 4×32 bit
            var a = (out[base] | (out[base + 1] << 8) | (out[base + 2] << 16) | (out[base + 3] << 24)) >>> 0;
            var b = (out[base + 4] | (out[base + 5] << 8) | (out[base + 6] << 16) | (out[base + 7] << 24)) >>> 0;
            var c = (out[base + 8] | (out[base + 9] << 8) | (out[base + 10] << 16) | (out[base + 11] << 24)) >>> 0;
            var d = (out[base + 12] | (out[base + 13] << 8) | (out[base + 14] << 16) | (out[base + 15] << 24)) >>> 0;

            // 小端→大端
            a = bswap32(a);
            b = bswap32(b);
            c = bswap32(c);
            d = bswap32(d);

            // XOR + rotate
            a = (a ^ k0) >>> 0;
            b = (ror32(b, 24) ^ k1) >>> 0;
            c = (ror32(c, 16) ^ k2) >>> 0;
            d = (ror32(d, 8) ^ k3) >>> 0;

            // 大端→小端
            a = bswap32(a);
            b = bswap32(b);
            c = bswap32(c);
            d = bswap32(d);

            // 写回
            out[base] = a & 0xff;
            out[base + 1] = (a >>> 8) & 0xff;
            out[base + 2] = (a >>> 16) & 0xff;
            out[base + 3] = (a >>> 24) & 0xff;
            out[base + 4] = b & 0xff;
            out[base + 5] = (b >>> 8) & 0xff;
            out[base + 6] = (b >>> 16) & 0xff;
            out[base + 7] = (b >>> 24) & 0xff;
            out[base + 8] = c & 0xff;
            out[base + 9] = (c >>> 8) & 0xff;
            out[base + 10] = (c >>> 16) & 0xff;
            out[base + 11] = (c >>> 24) & 0xff;
            out[base + 12] = d & 0xff;
            out[base + 13] = (d >>> 8) & 0xff;
            out[base + 14] = (d >>> 16) & 0xff;
            out[base + 15] = (d >>> 24) & 0xff;
        }

        function toSignedByte(v) {
            return (v << 24) >> 24;
        }

        var bb = Packages.java.nio.ByteBuffer.allocate(total);
        for (var i = 0; i < total; i++) {
            bb.put(i, toSignedByte(out[i]));
        }
        return bb.array();
    }

