    var others = [];
    for (var i = 1; i < parts.length; i += 2) {
        var n = parseInt(parts[i], 10);
        if (toneMap.hasOwnProperty(n)) {
            parts[i] = "[" + n + "]" + toneMap[n];
        } else {
            others.push(n);
            parts[i] = "";
        }
    }
    var ret = parts.join("").replace(/,+/g, ",").replace(/^,|,$/g, "");
    if (others.length) ret += "\n🎼其他音色：" + others.join(",");
    return ret;
}
function reSingle(n) {
    n = parseInt(n, 10);
    return toneMap.hasOwnProperty(n)
        ? "[" + n + "]" + toneMap[n]
        : "[" + n + "]";   
}

