@js:(function(result) {
    try {
        // 1. 解析页面源码（Legado环境中默认可调用org.jsoup，符合规则2.自定义js章节）
        var doc = org.jsoup.Jsoup.parse(result);
        // 2. 定位下一页按钮：匹配.page_info1容器内、含“下一页”文本的.page_link1（精准对应目标HTML）
        var nextLinkElem = doc.select("div.page_info1 a.page_link1:contains(下一页)").first();
        var nextUrl = "";

        if (nextLinkElem) {
            // 3. 提取下一页链接，处理空值（避免获取到null/undefined，符合Legado变量类型要求）
            nextUrl = nextLinkElem.attr("href") || "";
            // 4. 匹配目标URL格式“/arttype/24-数字.html”，提取页码（如24-2.html中的2）
            var pageMatch = nextUrl.match(/arttype\/24-(\d+)\.html/);

            if (pageMatch && pageMatch[1]) {
                // 5. 校验页码为纯数字（避免NaN，符合Legado对数值类型的要求）
                var nextPage = /^\d+$/.test(pageMatch[1]) ? parseInt(pageMatch[1], 10) : 0;
                // 6. 页码控制：≤10保留链接，否则设为空（Legado空值停止加载下一页，符合规则7.目录章节）
                if (nextPage > 10) {
                    nextUrl = "";
                }
            } else {
                // URL格式不符，视为无效链接，返回空
                nextUrl = "";
            }
        }

        // 7. 返回结果：单个字符串（Legado nextTocUrl支持单个URL，空值停止，符合规则7.目录章节）
        return nextUrl;
    } catch (e) {
        // 8. 异常兜底：返回空字符串（避免脚本报错中断加载，符合规则9.补充说明的容错建议）
        return "";
    }
})(result)

